import hashlib, os
from pathlib import Path

def blob(path):
    data = path.read_bytes()
    return hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\\0' + data).digest()

def tree(path):
    items=[]
    for child in path.iterdir():
        if child.is_symlink():
            data=os.readlink(child).encode()
            digest=hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\\0' + data).digest()
            items.append((child.name, False, b'120000', digest))
        elif child.is_dir():
            items.append((child.name, True, b'40000', tree(child)))
        elif child.is_file():
            mode=b'100755' if os.access(child, os.X_OK) else b'100644'
            items.append((child.name, False, mode, blob(child)))
    items.sort(key=lambda x: (x[0] + ('/' if x[1] else '')).encode())
    body=b''.join(mode+b' '+name.encode()+b'\\0'+digest for name,_,mode,digest in items)
    return hashlib.sha1(b'tree '+str(len(body)).encode()+b'\\0'+body).digest()
print(tree(Path('specification/standards')).hex())
PY"

